import sys

def diff(x, y):
    z = x - y
    if z >= 0:
        return z
    return z * (-1)

def main():
    s = sys.stdin.readline().strip()

    m = {}
    m_rev = {}
    for i in range(1, 27):
        m[chr(ord('a') + i - 1)] = i
    for i in range(26, 0, -1):
        m_rev[chr(ord('z') - (26 - i))] = i

    ans = 0
    for i in range(len(s)):
        if i == 0:
            a = diff(m[s[i]], m['a'])
            b = diff(a, 26)
        else:
            a = diff(m[s[i]], m[s[i - 1]])
            b = diff(a, 26)
        if a < b:
            ans += a
        else:
            ans += b

    print(ans)

if __name__ == "__main__":
    main()
